     1	import { useEffect, useState } from 'react';
     2	import OwnVoice from './pages/OwnVoice.jsx';
     3	import Home from './pages/Home.jsx';
     4	import VoiceCall from './pages/VoiceCall.jsx';
     5	import ClinicList from './pages/ClinicList.jsx';
     6	import LiveHandoff from './pages/LiveHandoff.jsx';
     7	import PhoneCall from './pages/PhoneCall.jsx';
     8	import Plan from './pages/Plan.jsx';
     9	import { strings, detectLang, saveLang } from './i18n.js';
    10	import { primeSpeech } from './agents/speech.js';
    11	import { buildSummary } from './utils/summary.js';
    12	import { IS_LIVE_PHONE } from './agents/index.js';
    13	import { PHONE_AGENT_URL } from './config.js';
    14	
    15	const GRADIUM_KEY = 'pawse.gradium';
    16	function loadGradiumChoice() {
    17	  try {
    18	    return localStorage.getItem(GRADIUM_KEY) !== '0'; // on by default, the owner can turn it off
    19	  } catch {
    20	    return true;
    21	  }
    22	}
    23	
    24	// home → voice call with Pawse → advice
    25	//   → "call the vet": clinic list → Pawse calls the chosen clinic
    26	//   → "call the insurer": Pawse calls the insurer
    27	//   → plan (summary)
    28	export default function App() {
    29	  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
    30	  const [lang, setLangState] = useState(detectLang);
    31	  const [triage, setTriage] = useState(null);
    32	  const [vet, setVet] = useState(null);
    33	  const [insurance, setInsurance] = useState(null);
    34	  const [clinic, setClinic] = useState(null);
    35	  const [target, setTarget] = useState(null);
    36	  const [rehearsal, setRehearsal] = useState(false);
    37	  const [gradiumOn, setGradiumOnState] = useState(loadGradiumChoice);
    38	  const [voiceStatus, setVoiceStatus] = useState(null);
    39	
    40	  const setGradiumOn = (on) => {
    41	    setGradiumOnState(on);
    42	    try {
    43	      localStorage.setItem(GRADIUM_KEY, on ? '1' : '0');
    44	    } catch {
    45	      /* storage unavailable */
    46	    }
    47	  };
    48	
    49	  // Live phone calls only: is Gradium configured, and does this session have its own German voice?
    50	  useEffect(() => {
    51	    if (!IS_LIVE_PHONE) return undefined;
    52	    let alive = true;
    53	    fetch(`${PHONE_AGENT_URL || ''}/api/v1/voice/status`)
    54	      .then((r) => (r.ok ? r.json() : null))
    55	      .then((s) => alive && s && setVoiceStatus(s))
    56	      .catch(() => {});
    57	    return () => {
    58	      alive = false;
    59	    };
    60	  }, []);
    61	  // Unknown status: still offer Gradium; the call falls back to the browser voice on 503.
    62	  const gradiumAvailable = IS_LIVE_PHONE && (!voiceStatus || voiceStatus.gradium_configured === true);
    63	  const ownVoice = !!(voiceStatus && voiceStatus.my_voice_ready);
    64	
    65	  const t = strings[lang] || strings.en;
    66	  const Handoff = IS_LIVE_PHONE && !rehearsal ? LiveHandoff : PhoneCall;
    67	
    68	  const setLang = (l) => {
    69	    setLangState(l);
    70	    saveLang(l);
    71	  };
    72	
    73	  useEffect(() => {
    74	    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
    75	  }, [lang]);
    76	
    77	  const startCall = () => {
    78	    primeSpeech(); // unlock speech on iOS while we are inside the tap
    79	    setTriage(null);
    80	    setVet(null);
    81	    setInsurance(null);
    82	    setClinic(null);
    83	    setView('voice');
    84	  };
    85	
    86	  const call = (to) => {
    87	    setRehearsal(false);
    88	    primeSpeech();
    89	    if (to === 'vet') {
    90	      setView('clinics');
    91	      return;
    92	    }
    93	    setTarget(to);
    94	    setView('phone');
    95	  };
    96	
    97	  const pickClinic = (c) => {
    98	    setRehearsal(false);
    99	    primeSpeech();
   100	    setClinic(c);
   101	    setTarget('vet');
   102	    setView('phone');
   103	  };
   104	
   105	  const callDone = (result) => {
   106	    if (result && target === 'vet') setVet(result);
   107	    if (result && target === 'insurance') setInsurance(result);
   108	    setView(triage ? 'plan' : 'home');
   109	  };
   110	
   111	  if (view === 'ownvoice') return <OwnVoice onBack={() => setView('home')} />;
   112	  if (view === 'voice') {
   113	    return (
   114	      <VoiceCall
   115	        t={t}
   116	        lang={lang}
   117	        triage={triage}
   118	        vet={vet}
   119	        insurance={insurance}
   120	        onTriage={setTriage}
   121	        onCall={call}
   122	        onEnd={() => setView(triage ? 'plan' : 'home')}
   123	      />
   124	    );
   125	  }
   126	  if (view === 'clinics') {
   127	    // Going back from the list never restarts the voice call: show the plan instead.
   128	    return <ClinicList t={t} lang={lang} triage={triage} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
   129	  }
   130	  if (view === 'phone') {
   131	    return (
   132	      <Handoff
   133	        key={`${target}-${clinic ? clinic.id : ''}`}
   134	        t={t}
   135	        lang={lang}
   136	        target={target}
   137	        clinic={target === 'vet' ? clinic : null}
   138	        gradium={gradiumAvailable ? { on: gradiumOn, ownVoice, set: setGradiumOn } : null}
   139	        context={{
   140	          gradiumConsent: gradiumAvailable && gradiumOn,
   141	          voice: ownVoice ? 'my_voice' : 'standard',
   142	          summary: buildSummary({ lang, triage, vet, insurance }),
   143	          clinic: target === 'vet' ? clinic : undefined,
   144	          estimate: vet ? vet.estimate : undefined,
   145	          homeVisitFee: vet ? vet.homeVisitFee : undefined,
   146	        }}
   147	        onDone={callDone}
   148	        onRehearse={() => { setGradiumOn(false); setRehearsal(true); }}
   149	      />
   150	    );
   151	  }
   152	  if (view === 'plan' && triage) {
   153	    return (
   154	      <Plan
   155	        t={t}
   156	        lang={lang}
   157	        triage={triage}
   158	        vet={vet}
   159	        insurance={insurance}
   160	        onCall={call}
   161	        onRestart={() => setView('home')}
   162	      />
   163	    );
   164	  }
   165	  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} onOwnVoice={() => setView('ownvoice')} />;
   166	}
